<body>
  <div class="choice-container">
    <div class="choice-toggle">故事分支</div>
    <div class="choice-panel">
      <div class="choice-content">
        <div class="choice-item" data-choice="$1">$1</div>
        <div class="choice-item" data-choice="$2">$2</div>
        <div class="choice-item" data-choice="$3">$3</div>
        <div class="choice-item" data-choice="$4">$4</div>
        <div class="choice-item" data-choice="$5">$5</div>
      </div>
      <div class="choice-footer">Created by Yukino</div>
    </div>
  </div>

  <script>
    (function() {
      const container = document.querySelector('.choice-container');
      if (!container) return;

      const toggle = container.querySelector('.choice-toggle');
      const panel = container.querySelector('.choice-panel');
      const items = container.querySelectorAll('.choice-item');

      toggle.addEventListener('click', function() {
        const isActive = panel.classList.contains('active');

        if (isActive) {
          panel.classList.remove('active');
        } else {
          panel.classList.add('active');

          items.forEach((item, index) => {
            item.style.animation = 'none';
            setTimeout(() => {
              item.style.animation = `itemSlideIn 0.4s ease-out forwards ${0.1 + index * 0.05}s`;
            }, 10);
          });
        }
      });

      items.forEach(item => {
        item.addEventListener('click', async function() {
          const choiceText = this.getAttribute('data-choice');

          this.style.color = '#00bfff';
          this.style.transition = 'color 0.2s ease';

          await triggerSlash(`/setinput ${choiceText}`);

          setTimeout(() => {
            panel.classList.remove('active');
          }, 200);
        });
      });

      document.addEventListener('click', function(e) {
        if (!container.contains(e.target)) {
          panel.classList.remove('active');
        }
      });
    })();
  </script>
</body>
